"""Script was generated by Claude.

Run every DQ case offline and compare each result with what we expect.
"""

import sys
from pathlib import Path

from ingestion.dq_checks import check_billing, check_crm
from ingestion.load import get_id, read_all

PASSES = "passes"

# file: PASSES, or text that the error must contain
FILE_CASES = {
    "data/batch_1/crm_customers.csv": PASSES,
    "data/batch_1/billing_customers.csv": PASSES,
    "data/bad_batch/crm_customers.csv": PASSES,
    "data/bad_batch/billing_customers.csv": "DataQualityError: BILLING batch encountered 2 problems",
    "data/dq_cases/billing_duplicate_account.csv": "Duplicate ACCOUNT_NUMBER: 1001, row 2.",
    "data/dq_cases/billing_empty_id.csv": "Empty BILLING_ID, row 2.",
    "data/dq_cases/billing_short_row.csv": "DataQualityError: BILLING: Too few fields, row 1.",
    "data/dq_cases/billing_two_unmapped.csv": PASSES,
    "data/dq_cases/billing_unknown_plan.csv": "Plan value GOLD, row 2",
    "data/dq_cases/crm_duplicate_column_case.csv": "Duplicate cleaned column detected: CRM_ID.",
    "data/dq_cases/crm_duplicate_column_exact.csv": "Duplicate cleaned column detected: CRM_ID.",
    "data/dq_cases/crm_duplicate_id.csv": "Duplicate CRM_ID: C-001, row 2.",
    "data/dq_cases/crm_empty_file.csv": "ValueError: No headers returned for crm_empty_file.csv",
    "data/dq_cases/crm_empty_id.csv": "Empty CRM_ID, row 2.",
    "data/dq_cases/crm_header_only.csv": "DataQualityError: CRM: Rows are empty.",
    "data/dq_cases/crm_long_first_row.csv": "DataQualityError: CRM: Too many fields, row 1.",
    "data/dq_cases/crm_long_second_row.csv": "DataQualityError: CRM: Too many fields, row 2.",
    "data/dq_cases/crm_missing_column.csv": "Missing columns: ['ACCOUNT_NUMBER'].",
    "data/dq_cases/crm_short_row_city.csv": "DataQualityError: CRM: Too few fields, row 1.",
    "data/dq_cases/crm_short_row_id_only.csv": "DataQualityError: CRM: Too few fields, row 1.",
    "data/dq_cases/crm_trailing_commas.csv": PASSES,
    "data/dq_cases/crm_two_unmapped.csv": PASSES,
}

# folder: batch ID, or text that the error must contain
ID_CASES = {
    "data/batch_1": "1",
    "data/bad_batch": "-1",
    "data/whatever": "ValueError: Batch name 'whatever'",
}


def run_file(path: Path) -> str:
    try:
        headers, rows = read_all(path.parent, path.name)
        if path.name.startswith("crm"):
            check_crm(headers, rows)
        else:
            check_billing(headers, rows)
    except Exception as e:
        return f"{type(e).__name__}: {e}"
    return PASSES


def run_id(path: Path) -> str:
    try:
        return str(get_id(path))
    except Exception as e:
        return f"{type(e).__name__}: {e}"


def report(name: str, matches: bool, expected: str, actual: str) -> int:
    """Print one result and return the number of failures: 0 or 1."""
    if matches:
        print(f"ok    {name}")
        return 0
    print(f"FAIL  {name}\n      expected: {expected}\n      actual:   {actual}")
    return 1


def run_cases() -> None:
    failures = 0

    for name, expected in FILE_CASES.items():
        actual = run_file(Path(name))
        if expected == PASSES:
            matches = actual == PASSES
        else:
            matches = expected in actual
        failures += report(name, matches, expected, actual)

    for name, expected in ID_CASES.items():
        actual = run_id(Path(name))
        if expected.startswith("ValueError"):
            matches = expected in actual
        else:
            matches = actual == expected
        failures += report(name, matches, expected, actual)

    print(f"\n{len(FILE_CASES) + len(ID_CASES)} cases, {failures} failed.")
    if failures:
        sys.exit(1)


if __name__ == "__main__":
    run_cases()
